function rand(a, b, seed) {
  let value = seed >>> 0;
  value ^= value << 13;
  value ^= value >>> 17;
  value ^= value << 5;
  return a + ((value >>> 0) / 4294967296) * (b - a);
}

function seedFromId(id) {
  return Array.from(id).reduce(
    (seed, character) => (Math.imul(seed, 31) + character.charCodeAt(0)) >>> 0,
    0,
  ) || 1;
}

function Stars({ count }) {
  const id = useId();
  const seed = seedFromId(id);
  const stars = useMemo(() => Array.from({ length: count }, (_, index) => {
    const offset = seed + index * 6;
    return {
      x: rand(0, 100, offset + 1), y: rand(0, 100, offset + 2), s: rand(1, 3, offset + 3),
      t: rand(2, 6, offset + 4), dl: rand(0, 6, offset + 5),       dr: rand(20, 36, offset + 6),
      fallDelay: rand(-32, 0, offset + 7),
    };
  }), [count, seed]);
  return (
    <div className="stars" aria-hidden="true">
      {stars.map((s, i) => (
        <span key={i} style={{
          left: `${s.x}%`, top: `${s.y}%`, width: s.s, height: s.s,
          animationDuration: `${s.t}s, ${s.dr}s`,           animationDelay: `${s.dl}s, ${s.fallDelay}s`,
        }} />
      ))}
    </div>
  );
}

function FloatingIcons({ local = false }) {
  const id = useId();
  const seed = seedFromId(id);
  const items = useMemo(() => ICONS.map((ic, index) => {
    const offset = seed + index * 6;
    return {
      ic, x: rand(0, 96, offset + 1), size: rand(22, 46, offset + 2), dur: rand(28, 60, offset + 3),
      delay: rand(-60, 0, offset + 4), sway: rand(20, 70, offset + 5), op: rand(0.12, 0.28, offset + 6),
    };
  }), [seed]);
  return (
    <div className={local ? "float-icons local" : "float-icons"} aria-hidden="true">
      {items.map((it, i) => (
        <span key={i} style={{
          left: `${it.x}%`, fontSize: it.size, opacity: local ? Math.min(it.op * 1.6, 0.4) : it.op,
          animationDuration: `${it.dur}s`, animationDelay: `${it.delay}s`,
          "--sway": `${it.sway}px`,
        }}>{it.ic}</span>
      ))}
    </div>
  );
}

