function Testimonials() {
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(false);
  const [expanded, setExpanded] = useState({});
  const pointerStart = useRef(null);
  const maxIndex = TESTIMONIAL_SLIDES.length - 1;

  useEffect(() => {
    if (paused || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return undefined;
    const timer = window.setInterval(() => {
      setIndex((current) => current >= maxIndex ? 0 : current + 1);
    }, 5000);
    return () => window.clearInterval(timer);
  }, [index, maxIndex, paused]);

  const goTo = (nextIndex) => {
    setIndex(Math.max(0, Math.min(nextIndex, maxIndex)));
  };

  const handlePointerUp = (event) => {
    if (pointerStart.current === null) return;
    const distance = event.clientX - pointerStart.current;
    pointerStart.current = null;
    if (distance < -50) goTo(index >= maxIndex ? 0 : index + 1);
    if (distance > 50) goTo(index <= 0 ? maxIndex : index - 1);
  };

  return (
    <section className="testimonials" aria-labelledby="testimonials-title">
      <Stars count={48} />
      <div className="testimonials-content">
        <header className="testimonials-heading">
          <span className="section-kicker">Words from our community</span>
          <h2 id="testimonials-title">Readings that changed their path</h2>
          <p>Experiences shared by people who found guidance with Jeevan Jyotish.</p>
        </header>
        <div
          className="testimonial-viewport"
          role="region"
          aria-roledescription="carousel"
          aria-label="Client testimonials"
          tabIndex={0}
          onMouseEnter={() => setPaused(true)}
          onMouseLeave={() => setPaused(false)}
          onFocus={() => setPaused(true)}
          onBlur={(event) => {
            if (!event.currentTarget.contains(event.relatedTarget)) setPaused(false);
          }}
          onPointerDown={(event) => {
            pointerStart.current = event.clientX;
            event.currentTarget.setPointerCapture(event.pointerId);
          }}
          onPointerUp={handlePointerUp}
          onPointerCancel={() => { pointerStart.current = null; }}
          onKeyDown={(event) => {
            if (event.key === "ArrowLeft") goTo(index <= 0 ? maxIndex : index - 1);
            if (event.key === "ArrowRight") goTo(index >= maxIndex ? 0 : index + 1);
          }}
        >
          <div
            className="testimonial-track"
            style={{ transform: `translate3d(-${index * 100}%, 0, 0)` }}
            aria-live="polite"
          >
            {TESTIMONIAL_SLIDES.map((slide, slideIndex) => (
              <div
                className={`testimonial-slide${slideIndex === index ? " is-active" : ""}`}
                key={slideIndex}
                aria-label={`Slide ${slideIndex + 1}`}
              >
                {slide.map((testimonial, cardIndex) => {
                  const isExpanded = Boolean(expanded[testimonial.name]);
                  return (
                    <article
                      className={`testimonial-card${isExpanded ? " expanded" : ""}`}
                      key={testimonial.name}
                      style={{
                        "--float-delay": `${cardIndex * -1.5}s`,
                        "--enter-delay": `${cardIndex * 0.12}s`,
                      }}
                    >
                      <span className="testimonial-mark" aria-hidden="true">✦ &nbsp; CLIENT STORY</span>
                      <p>{testimonial.text}</p>
                      <button
                        type="button"
                        className="testimonial-read-more"
                        aria-expanded={isExpanded}
                        onClick={() => setExpanded((current) => ({
                          ...current,
                          [testimonial.name]: !current[testimonial.name],
                        }))}
                      >
                        {isExpanded ? "Show less" : "Read full story"}
                      </button>
                      <div className="testimonial-author">
                        <img src={testimonial.image.src} alt="" loading="lazy" decoding="async" />
                        <div>
                          <h3>{testimonial.name}</h3>
                          <span>{testimonial.location}</span>
                        </div>
                      </div>
                    </article>
                  );
                })}
              </div>
            ))}
          </div>
        </div>
        <div className="testimonial-controls" aria-label="Testimonial navigation">
          <button type="button" className="testimonial-arrow" aria-label="Previous testimonials"
            onClick={() => goTo(index <= 0 ? maxIndex : index - 1)}>←</button>
          <div className="testimonial-dots">
            {Array.from({ length: maxIndex + 1 }, (_, dotIndex) => (
              <button
                type="button"
                key={dotIndex}
                className={`testimonial-dot${dotIndex === index ? " active" : ""}`}
                aria-label={`Go to testimonial group ${dotIndex + 1}`}
                aria-current={dotIndex === index ? "true" : undefined}
                onClick={() => goTo(dotIndex)}
              />
            ))}
          </div>
          <button type="button" className="testimonial-arrow" aria-label="Next testimonials"
            onClick={() => goTo(index >= maxIndex ? 0 : index + 1)}>→</button>
        </div>
      </div>
    </section>
  );
}

